const fs = require('fs');

const N = Number(fs.readFileSync(0, 'utf8').trim());

function countSuitable(x) {
    if (x < 3) return 0;
    const oddCount = Math.floor((x - 1) / 2);
    const multipleOfFourCount = Math.max(0, Math.floor(x / 4) - 1);
    return oddCount + multipleOfFourCount;
}

let low = 3;
let high = 2 * N + 10;

while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (countSuitable(mid) >= N) high = mid;
    else low = mid + 1;
}

